<script setup lang="ts">
import {computed,ref,watch,onBeforeUnmount} from 'vue'
import TransportTimeFields from './TransportTimeFields.vue'
import {entryFields,entryNames,transportTypes,transportType,transportSpecific,type Entry,type TransportType} from './entries'
import PrivatePreview from '../admin/PrivatePreview.vue'
import {request} from '../api'
import type {Asset} from '../admin/archive'
const props=defineProps<{value:Entry;disabled?:boolean;recordDate?:string}>()
const emit=defineEmits<{(e:'validity',value:boolean):void}>()
const siteZone=ref('');let alive=true,zoneRequested=false
watch(()=>props.value.kind,async kind=>{emit('validity',true);if(kind!=='t'||zoneRequested)return;zoneRequested=true;try{const result=await request('/admin/calendar/notification');if(alive&&typeof result?.timezone==='string')siteZone.value=result.timezone}catch{/* User may select an explicit zone; never guess browser timezone. */}},{immediate:true})
onBeforeUnmount(()=>{alive=false})
const vehicle=computed({get:()=>transportType(props.value.fields.transport_type||'高铁／动车'),set:(v:TransportType)=>{const old=props.value.fields.transport_type;if(old&&!transportTypes.includes(old as TransportType)&&!props.value.fields.legacy_transport_type)props.value.fields.legacy_transport_type=old;props.value.fields.transport_type=v}})
const customVehicle=computed({get:()=>props.value.fields.vehicle_name||(vehicle.value==='其他'&&props.value.fields.transport_type!=='其他'?props.value.fields.transport_type||'':''),set:(name:string)=>{props.value.fields.vehicle_name=name}})
const nameLabel=computed(()=>props.value.kind!=='t'?'名称':['高铁／动车','普通列车'].includes(vehicle.value)?'车次':vehicle.value==='飞机'?'航班号':vehicle.value==='轮船'?'航次':'名称或标题')
const common=computed(()=>props.value.kind==='t'?[['departure','出发地'],['destination','目的地'],['description','备注'],...(props.value.fields.review?[['review','个人感受']]:[])]:entryFields[props.value.kind])
const optional=computed(()=>props.value.kind==='t'?transportSpecific[vehicle.value]:[])
const legacy=computed(()=>{const known=new Set([...common.value,...optional.value].map(f=>f[0]));for(const k of ['place_id','transport_type','departure_at','arrival_at','departure_zone','arrival_zone','independent_zones'])known.add(k);return Object.keys(props.value.fields).filter(k=>!known.has(k)&&!!props.value.fields[k]?.trim())})
const suggestions:Record<string,string[]>={meal_period:['早餐','午餐','晚餐','下午茶','夜宵','其他'],show_type:['演唱会','音乐节','音乐会','音乐剧','话剧','其他'],direction:['收到礼物','赠送礼物'],occasion:['生日','纪念日','节日','旅行','日常','其他']}
function fieldLabel(key:string,label:string){return props.value.kind==='g'&&key==='person'?/赠送|送出|送给/.test(props.value.fields.direction||'')?'收礼人':/收到|收下/.test(props.value.fields.direction||'')?'赠送人':'相关人物':label}
const places=ref<any[]>([]),placeSearch=ref('')
async function findPlaces(){try{places.value=(await request('/admin/archive/places?q='+encodeURIComponent(placeSearch.value)+'&page_size=50')).items}catch{error.value='读取地点失败'}}
const photos=ref<Asset[]>([]),search=ref(''),error=ref('')
async function load(){try{photos.value=(await request('/admin/archive/media?q='+encodeURIComponent(search.value)+'&page_size=24')).items;error.value=''}catch{error.value='无法读取媒体，请重试'}}
function toggle(id:string){const i=props.value.media_ids.indexOf(id);if(i>=0)props.value.media_ids.splice(i,1);else if(props.value.media_ids.length<100)props.value.media_ids.push(id)}
</script>
<template><div class="entry-form"><label>记录类型<select aria-label="记录类型" v-model="value.kind" :disabled="disabled"><option v-for="(name,k) in entryNames" :value="k">{{name}}</option></select></label><label>{{nameLabel}}<input v-model="value.name" maxlength="200" required :disabled="disabled"/></label><template v-if="value.kind==='l'||value.kind==='f'"><label>搜索已有地点<input v-model="placeSearch"/></label><button type="button" @click="findPlaces">查找地点</button><label>关联地点<select aria-label="关联地点" v-model="value.fields.place_id"><option value="">不指定</option><option v-for="p in places" :key="p.id" :value="p.id">{{p.name}} · {{p.region||p.city}}</option></select></label></template><label v-if="value.kind==='t'">交通类型<select aria-label="交通类型" v-model="vehicle" :disabled="disabled"><option v-for="type in transportTypes" :key="type">{{type}}</option></select></label><label v-for="[key,label,type] in common" :key="key">{{fieldLabel(key!,label!)}}<textarea v-if="key==='review'||key==='description'" v-model="value.fields[key]" rows="3" maxlength="4000" :disabled="disabled"/><input v-else v-model="value.fields[key!]" :type="type||'text'" :list="suggestions[key!]?'entry-options-'+value.id+'-'+key:undefined" maxlength="4000" :disabled="disabled"/><datalist v-if="suggestions[key!]" :id="'entry-options-'+value.id+'-'+key"><option v-for="option in suggestions[key!]" :key="option" :value="option"/></datalist></label><TransportTimeFields v-if="value.kind==='t'" :value="value" :site-zone="siteZone" :record-date="recordDate" :disabled="disabled" @validity="emit('validity',$event)"/><details v-if="optional.length" :open="optional.some(([key])=>!!value.fields[key])"><summary>更多信息（选填）</summary><label v-for="[key,label] in optional" :key="key">{{label}}<input v-if="key==='vehicle_name'" v-model="customVehicle" maxlength="4000" :disabled="disabled"/><input v-else v-model="value.fields[key]" maxlength="4000" :disabled="disabled"/></label></details><details v-if="legacy.length" open><summary>历史兼容信息（已保留）</summary><label v-for="key in legacy" :key="key">{{entryFields[value.kind].find(f=>f[0]===key)?.[1]||key}}<textarea v-model="value.fields[key]" rows="2" maxlength="4000" :disabled="disabled"/></label></details><details open><summary>票据和相关照片（已选 {{value.media_ids.length}} 张）</summary><label>搜索媒体<input v-model="search" :disabled="disabled"/></label><button type="button" :disabled="disabled" @click="load">选择已有照片</button><p role="status">{{error}}</p><div class="entry-media"><button v-for="p in photos" :key="p.id" type="button" :aria-pressed="value.media_ids.includes(p.id)" :disabled="disabled" @click="toggle(p.id)"><PrivatePreview :id="p.id" :alt="p.alt"/>{{p.title||p.filename}}</button></div><div v-for="id in value.media_ids" :key="id" class="entry-selected"><PrivatePreview :id="id" alt="关联照片"/><button type="button" :disabled="disabled" @click="toggle(id)">移除此图片关联</button></div></details></div></template>
<style scoped>.entry-form{min-width:0}.entry-form label{display:block}.entry-form input,.entry-form select,.entry-form textarea{width:100%;max-width:100%;box-sizing:border-box}.entry-media{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.entry-media img,.entry-selected img{max-width:100%;max-height:120px}.entry-media button[aria-pressed=true]{outline:2px solid var(--accent)}.entry-selected{display:inline-block;width:45%;margin:2%}.body-editor .entry-form textarea{min-height:6em;height:auto}
</style>
